# Plain round-robin load balancer in front of three independent seller instances.
# No application state here: every seller talks to the same Postgres, which is the
# single source of truth (row lock, one-snapshot fast path, constraints).
worker_processes auto;
events { worker_connections 8192; }

http {
    access_log off;   # nginx only; the sellers' own access logs stay on (per-instance counts)

    upstream sellers {
        server seller1:8000;
        server seller2:8000;
        server seller3:8000;
        # Reuse upstream connections: without this nginx opens a new TCP connection per
        # request (~50k/min at 833/s), exhausting ephemeral ports via TIME_WAIT.
        keepalive 256;
    }

    server {
        listen 80;
        location / {
            proxy_pass http://sellers;
            proxy_http_version 1.1;
            proxy_set_header Connection "";
            proxy_read_timeout 60s;
            # Which instance served this response (evidence of distribution only).
            # nginx does not retry POST on another upstream by default (non-idempotent).
            add_header X-Upstream $upstream_addr always;
        }
    }
}

