ready = datetime.datetime.strptime(m.group(1), "%Y-%m-%d %H:%M:%S.%f").replace(tzinfo=datetime.timezone.utc).timestamp() - t0
ans = lambda r: r["i"] / rate + r["latency_ms"] / 1000
rows = {t["user_id"]: t["ticket_number"] for t in d["status"]["tickets"]}
first_ok = {}
for r in sorted((r for r in d["records"] if r["status"] == 200), key=ans):
    first_ok.setdefault(r["ticket_number"], ans(r))
print(f"kill event t={kill:.3f}s | die t={die:.3f}s | Postgres 'ready to accept connections' t={ready:.3f}s")
for label, lo, hi in (("before the kill event", -1e9, kill), ("between kill and Postgres ready", kill, ready), ("after Postgres ready", ready, 1e9)):
    ns = sorted(n for n, t in first_ok.items() if lo <= t < hi)
    print(f"  tickets first confirmed {label}: {len(ns)}" + (f" -> #{ns[0]}..#{ns[-1]}" if ns else "") +
          (f" at t={min(first_ok[n] for n in ns):.3f}..{max(first_ok[n] for n in ns):.3f}s" if ns else ""))
st = defaultdict(list)
for r in d["records"]:
    st[r["request_id"]].append(r)
print("\nrequest_ids that got a 500 near the kill AND hold a ticket row (every copy shown):")
for q, rs in st.items():
    if rs[0]["user_id"] in rows and any(r["status"] == 500 and kill - 0.2 <= ans(r) <= kill + 1.5 for r in rs):
        print(f"  {q} ticket #{rows[rs[0]['user_id']]}: " + "; ".join(
            f"{r['status']} answered t={ans(r):.3f}s (sent t={r['i']/rate + r['send_lag_ms']/1000:.3f}s) via {r.get('upstream')}"
            + (f" ticket #{r['ticket_number']}" if r['status'] == 200 else "") for r in sorted(rs, key=ans)))
cls = Counter()
for q, rs in st.items():
    codes = {r["status"] for r in rs}
    cls["(2) committed + acknowledged" if 200 in codes else "sold out only (409)" if codes == {409}
        else "(3) committed but UNACKNOWLEDGED" if rs[0]["user_id"] in rows else "(1) no committed ticket"] += 1
print("\nper unique request_id:"); [print(f"  {k}: {v}") for k, v in sorted(cls.items())]
EOF

