document.getElementById('sweepChart').scrollIntoView({block: 'start'});
// verify every marker sits at its exact data value
const svg = document.getElementById('sweepChart'), vb = svg.viewBox.baseVal, W = vb.width, H = vb.height, m = { l: 56, r: 16, t: 14, b: 40 };
const yinv = py => 750 + (H - m.b - py) / (H - m.t - m.b) * 750;
const marks = [...svg.querySelectorAll('circle[fill="transparent"]')].map(c => Math.round(yinv(+c.getAttribute('cy')) * 10) / 10);
({ markerValues: marks, expected: DATA.story.sweep.earlier_833.map(r => r.served).concat(DATA.story.sweep.rows.map(r => r.served)) })

