// One vertical sequence so it reads at any width (the example ticket number is illustrative).
const svg = $("cuaFlow"), W = svg.clientWidth || 480, cx = Math.min(W / 2, 150), bw = Math.min(250, W - 16);
const H = 470; svg.setAttribute("viewBox", `0 0 ${W} ${H}`); svg.setAttribute("height", H); svg.innerHTML = "";
const bx = Math.max(bw / 2 + 4, cx);
const steps = [["Buyer", "sends purchase, request_id A", null, "1  purchase"],
  ["Seller", "runs the purchase transaction", null, "2  COMMIT"],
  ["PostgreSQL", "commits: ticket 57 now exists", "--series-1", null],
  ["Buyer sees a failure", "…but already owns ticket 57", null, "4  retry, same request_id A"],
  ["Seller → PostgreSQL", "request_id A already has a ticket", null, null],
  ["Original ticket 57 returned", "no second ticket is created", "--good", null]];
steps.forEach(([title, sub, strong, next], i) => {
  const y = 26 + i * 80; box(svg, bx, y, bw, 38, title, sub, strong);
  if (i === 2) {   // the lost confirmation between PostgreSQL and the buyer
    el(svg, "line", { x1: bx, y1: y + 19, x2: bx, y2: y + 61, stroke: css("--axis"), "stroke-dasharray": "4 3" });
    const xs = el(svg, "text", { x: bx, y: y + 46, "text-anchor": "middle", fill: css("--bad-ink"), "font-size": 18, "font-weight": 700,
      stroke: css("--surface-1"), "stroke-width": 5, "paint-order": "stroke" }); xs.textContent = "✕";
    el(svg, "text", { x: bx + 14, y: y + 46, fill: css("--bad-ink"), stroke: css("--surface-1"), "stroke-width": 4, "paint-order": "stroke" }).textContent = "3  “COMMIT complete” lost";
  } else if (i < steps.length - 1) arrow(svg, bx, y + 19, bx, y + 61, next || "");
});

