// In-page links. Plain fragment navigation fails when this file is shown as a data: URL (some
// previewers do this): "#x" resolves to a navigation to data:…#x, which browsers block silently.
// So scroll to the section by id ourselves; the href stays as a fallback without JavaScript.
document.addEventListener("click", ev => {
  const a = ev.target.closest('a[href^="#"]');
  const target = a && document.getElementById(a.getAttribute("href").slice(1));
  if (!target) return;
  ev.preventDefault();
  const reduce = matchMedia("(prefers-reduced-motion: reduce)").matches;
  target.scrollIntoView({ behavior: reduce ? "auto" : "smooth", block: "start" });
  try { history.replaceState(null, "", a.getAttribute("href")); } catch (e) { /* not allowed for data: URLs; harmless */ }
});
function renderAll() {

